//
// Same arguments as RunLifecycle, so the control meets the checks
// the run does — including the ones you wrote, which no caller can bind
// for themselves.
func GreenLifecycle(
	t *testing.T,
	control suite.Subject[Lifecycle],
	opts ...LifecycleRunOpt,
) {
	t.Helper()
	var rc lifecycleRunConfig
	for _, o := range opts {
		o.applyTo(&rc)
	}
	fx := lifecycleNewFixture()
	for _, row := range rc.rows {
		rc.AddCheck(row.bind(fx))
	}
	rc.Fail(t, "GreenLifecycle")
	s := lifecycleSuite().With(rc.Extra...).Without(rc.Drops...)
	// Lent the doors the run answers, so a control is refused for being
	// wrong rather than for being unwired. Answering says why.
	prove.Green(t, s.Checks,
		control.Answering(suite.Doors(rc.Subjects...)))
}

