// --- Lifecycle's model tier -------------------------------------------
//
// Random sequences of Lifecycle's methods, run against every subject and
// something that judges them from outside. The rows on the run surface
// above carry it, and LifecycleSuite.Without declines any of them by name.
//
//	Reference: the subject's own factory — no reader/writer pair derives a store,
//	           so a second instance driven identically stands in: twins must
//	           agree, which catches nondeterminism and hidden shared state but
//	           not a subject wrong the same way twice; ref= raises the floor
//	Sequences: Close (lifecycle)
//	Not bound:
//	           AUTO-IDEMPOTENT-LIFECYCLE — observes state through no method here — no drain, no aggregate, no keyed read
//	           lifecycle differential — the reference is the subject's own factory, whose comparison already rides each law leg's actions; alone it catches nondeterminism and nothing a second instance shares
//
// lifecycleModelActions is the operation vocabulary both legs drive.
//
// One constructor per method shape, from the engine's action set rather
// than hand-written closures: the constructors record inputs and outputs
// into the trace a law reads, compare the two sides the same way for every
// action, and shrink a failing sequence to the shortest one that still
// fails.
func lifecycleModelActions() []model.Action[Lifecycle] {
	out := []model.Action[Lifecycle]{
		action.Lifecycle("Close",
			func(ctx context.Context, s lifecycle.Lifecycle) error {
				return s.Close(ctx)
			}),
	}
	return out
}

// lifecycleAssertRespectsContext binds AUTO-LIFECYCLE-RESPECTS-CONTEXT over the shared sequences.
//
// One law, and the run's only oracle — see [legs.Law]
// for why the differential is off on every law leg.
func lifecycleAssertRespectsContext(
	tb testing.TB,
	sub suite.Subject[Lifecycle],
) {
	tb.Helper()

	buildRef, tier := legs.Reference(tb, sub, func() Lifecycle { return sub.New(tb) })
	sub.NoteTier(tier)
	legs.Law(tb, sub,
		func() Lifecycle { return sub.New(tb) }, buildRef,
		lifecycleModelActions(),
		[]law.Law[Lifecycle]{
			law.LifecycleRespectsContext[lifecycle.Lifecycle]{
				Op: func(ctx context.Context, s lifecycle.Lifecycle) error {
					return s.Close(ctx)
				},
				Name: "Close",
			},
		})
}

